<?php require __DIR__.'/config/bootstrap.php';header('Content-Type: application/xml; charset=utf-8');echo '<?xml version="1.0" encoding="UTF-8"?>';?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><?php echo '<url><loc>'.e(site_url()).'</loc></url>';foreach(db()->query("SELECT slug,published_at FROM posts WHERE status='published'") as $p)echo '<url><loc>'.e(site_url('post.php?slug='.$p['slug'])).'</loc><lastmod>'.date('c',strtotime($p['published_at'])).'</lastmod></url>';?></urlset>